{
  "key_terms": [
    {
      "term": "Autoencoder",
      "definition": "Autoencoder is a type of model that learns representations by compressing input data and then reconstructing the original input from the compressed form. The process results in a different representation of the data, rather than strictly a better one.",
      "sentence_ids": [
        696,
        753,
        754
      ]
    },
    {
      "term": "Clustering",
      "definition": "Clustering is the problem of taking data and assigning each data point to a specific cluster. From a representation-learning perspective, clustering involves learning an encoder that outputs an integer representing the cluster assignment.",
      "sentence_ids": [
        763,
        766
      ]
    },
    {
      "term": "K-means",
      "definition": "K-means is an algorithm that finds k different clusters within a dataset, where each cluster is represented by its mean. It maps data points to integers such that each point is as close as possible to the mean of its assigned cluster.",
      "sentence_ids": [
        802,
        803
      ]
    },
    {
      "term": "Self-supervised learning",
      "definition": "Self-supervised learning is a method where the model learns representations by predicting parts of the raw data itself, rather than predicting predefined labels. This approach uses the machinery of supervised learning but defines the target output as a segment of the raw data.",
      "sentence_ids": [
        850,
        861
      ]
    },
    {
      "term": "Vector quantized autoencoder",
      "definition": "Vector quantized autoencoder is a model that is functionally the same as k-means, but it uses a non-linear function for the encoding process. This model aims to encode data into a set of integers while minimizing reconstruction error.",
      "sentence_ids": [
        833,
        834
      ]
    }
